/*
 * AVerMedia Live Gamer Extreme (GC550) - Hardware Initialization Sequence
 *
 * Copyright (C) 2026 Øystein Lie <oeystein@gengartv.com>
 *
 * CREDITS & ATTRIBUTION:
 * The USB-to-I2C bootstrap command sequence and hardware protocol documentation
 * (including the AT88SC CryptoMemory anti-clone analysis and removal, ADV7604
 * auto-colorspace fix, and board-state detection) were reverse-engineered and
 * documented by Chris Sawczuk (ChrisAJS) and contributors to the open-source
 * `lgx2userspace` project (https://github.com/ChrisAJS/lgx2userspace, GPL-3.0).
 *
 * Contains the 6,576 USB-to-I2C bridge setup transactions (PCA9539A GPIO,
 * ADV7604 HDMI receiver + EDID RAM, ADV7511 HDMI passthrough transmitter,
 * TLV320AIC3x analog audio codec, and Lattice ECP3 FPGA).
 *
 * SAFETY VERIFIED: All Atmel AT88SC CryptoMemory opcodes (0x05..0x07, 0x09)
 * are completely stripped. Only opcodes 0x01 (I2C Write), 0x02 (I2C Read),
 * 0x08 (Bridge Trigger), and 0x0E (EEPROM Read) are present.
 *
 * Entry format in gc550_init_blob:
 *   [0]      tx_len (1..36 bytes)
 *   [1..2]   rx_len (uint16 LE, 0 if write-only, >0 if Bulk IN 0x81 reply expected)
 *   [3..3+N] tx_bytes sent on Bulk OUT 0x01
 */

